/**
 * build-hds-tokens.mjs — regenerate Apply Board's token layer from HDS's DTCG source.
 *
 * Two outputs from one source of truth (hirobius.tokens.json):
 *   1. src/tokens/hds-tokens.css        — framework-neutral CSS variables (light + dark),
 *      alias chains preserved, NO Tailwind/preflight. Generated by Style Dictionary.
 *   2. src/theme/hds-palette.generated.ts — the light + dark palette resolved to gamut-safe
 *      HEX, with the jade brand applied. MUI needs literal colors (its alpha()/hover math
 *      can't operate on var()), so we resolve once at build time.
 *
 * This is a DEV-TIME step, not part of the production build. The deployed app imports the
 * committed generated files, so Vercel never needs the private package or a token.
 *
 * Regenerate (after an HDS update):
 *   npm i --no-save @hirobius/design-system@latest   # needs NODE_AUTH_TOKEN (read:packages)
 *   npm run tokens:build
 */
import StyleDictionary from 'style-dictionary';
import fs from 'node:fs';
import path from 'node:path';

const HDS = 'node_modules/@hirobius/design-system/hirobius.tokens.json';
const TOKENS_DIR = 'src/tokens';
const THEME_DIR = 'src/theme';

if (!fs.existsSync(HDS)) {
  console.error(
    '✗ @hirobius/design-system not installed.\n' +
      '  Install it (needs NODE_AUTH_TOKEN with read:packages) then retry:\n' +
      '    npm i --no-save @hirobius/design-system@latest\n' +
      '  See docs/adr/0001-consume-hds-via-tokens-on-mui.md',
  );
  process.exit(1);
}
fs.mkdirSync(TOKENS_DIR, { recursive: true });

// ── step A: Style Dictionary → vars-only CSS (light + dark) ──────────────────────
const toLegacy = (n) => {
  if (n && typeof n === 'object') {
    if ('$value' in n) {
      const t = { value: n.$value };
      if (n.$type) t.type = n.$type;
      if (n.$extensions) t.$extensions = n.$extensions;
      return t;
    }
    const o = {};
    for (const k of Object.keys(n)) if (k[0] !== '$') o[k] = toLegacy(n[k]);
    return o;
  }
  return n;
};
const refToVar = (v) => {
  if (v == null || typeof v === 'object') return null;
  const s = String(v).trim();
  const m = s.match(/^\{(.+)\}$/);
  return m ? `var(--${m[1].replace(/\./g, '-')})` : s;
};
const darkOf = (t) => t.original?.$extensions?.['com.figma.variables']?.modes?.Dark;

StyleDictionary.registerFormat({
  name: 'css/vars-light-dark',
  format: ({ dictionary }) => {
    const line = (t, v) => {
      const x = refToVar(v);
      return x == null ? null : `  --${t.path.join('-')}: ${x};`;
    };
    const light = dictionary.allTokens.map((t) => line(t, t.original.value)).filter(Boolean);
    const dark = dictionary.allTokens
      .filter((t) => {
        const d = darkOf(t);
        return d !== undefined && String(d) !== String(t.original.value);
      })
      .map((t) => line(t, darkOf(t)))
      .filter(Boolean);
    return [
      '/* GENERATED from @hirobius/design-system via Style Dictionary — variables only,',
      '   no Tailwind/preflight, alias chains preserved. Do not edit by hand. */',
      ':root {',
      ...light,
      '}',
      '',
      '/* dark overrides (from $extensions["com.figma.variables"].modes.Dark) */',
      '.dark {',
      ...dark,
      '}',
      '',
    ].join('\n');
  },
});

const sd = new StyleDictionary({
  tokens: toLegacy(JSON.parse(fs.readFileSync(HDS, 'utf8'))),
  log: { verbosity: 'silent', warnings: 'disabled' },
  platforms: {
    css: {
      buildPath: TOKENS_DIR + '/',
      files: [{ destination: 'hds-tokens.css', format: 'css/vars-light-dark' }],
    },
  },
});
await sd.buildAllPlatforms();

// ── step B: resolve light + dark palettes to hex for MUI (jade applied) ───────────
// OKLCH → sRGB hex (gamut-clamped on chroma) so MUI gets a parseable color.
const { cos, sin, PI, pow } = Math;
const unlin = (c) => (c <= 0.0031308 ? 12.92 * c : 1.055 * pow(c, 1 / 2.4) - 0.055);
const oklchToRgb = (L, C, H) => {
  const a = C * cos((H * PI) / 180),
    b = C * sin((H * PI) / 180);
  const l = (L + 0.3963377774 * a + 0.2158037573 * b) ** 3;
  const m = (L - 0.1055613458 * a - 0.0638541728 * b) ** 3;
  const s = (L - 0.0894841775 * a - 1.291485548 * b) ** 3;
  return [
    unlin(4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s),
    unlin(-1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s),
    unlin(-0.0041960863 * l - 0.7034186147 * m + 1.707614701 * s),
  ];
};
const inGamut = (rgb) => rgb.every((c) => c >= -0.001 && c <= 1.001);
const oklchToHex = (L, C, H) => {
  let c = C;
  while (c > 0 && !inGamut(oklchToRgb(L, c, H))) c -= 0.002;
  return (
    '#' +
    oklchToRgb(L, c, H)
      .map((v) =>
        Math.round(Math.min(1, Math.max(0, v)) * 255)
          .toString(16)
          .padStart(2, '0'),
      )
      .join('')
  );
};
const block = (css, sel) => {
  const i = css.indexOf(sel + ' {') >= 0 ? css.indexOf(sel + ' {') : css.indexOf(sel + '{');
  if (i < 0) return {};
  const s = css.indexOf('{', i);
  let d = 0,
    e = -1;
  for (let k = s; k < css.length; k++) {
    if (css[k] === '{') d++;
    else if (css[k] === '}') {
      d--;
      if (!d) {
        e = k;
        break;
      }
    }
  }
  const map = {};
  for (const m of css.slice(s + 1, e).matchAll(/--([a-z0-9-]+):\s*([^;]+);/gi))
    map[m[1]] = m[2].trim();
  return map;
};

const hdsCss = fs.readFileSync(path.join(TOKENS_DIR, 'hds-tokens.css'), 'utf8');
const jadeCss = fs.readFileSync(path.join(THEME_DIR, 'brand-jade.css'), 'utf8');
// light = :root only; dark = :root + .dark overrides (hds then jade)
const lightMap = { ...block(hdsCss, ':root'), ...block(jadeCss, ':root') };
const darkMap = { ...lightMap, ...block(hdsCss, '.dark'), ...block(jadeCss, '.dark') };

const resolveVal = (map, raw) => {
  let v = String(raw);
  for (let i = 0; i < 60 && /var\(/.test(v); i++) {
    v = v.replace(/var\(--([a-z0-9-]+)\)/gi, (_, n) => (map[n] != null ? map[n] : 'transparent'));
  }
  return v.trim();
};
const toHex = (v) => {
  const m = v.match(/^oklch\(\s*([\d.]+)\s+([\d.]+)\s+([\d.]+)/i);
  return m ? oklchToHex(+m[1], +m[2], +m[3]) : v;
};
const paletteFor = (map) => {
  const slot = (role) => toHex(resolveVal(map, `var(--role-${role})`));
  return {
    primaryMain: slot('primary'),
    primaryContrast: slot('primary-foreground'),
    errorMain: slot('destructive'),
    errorContrast: slot('destructive-foreground'),
    backgroundDefault: slot('background'),
    backgroundPaper: slot('card'),
    textPrimary: slot('foreground'),
    textSecondary: slot('muted-foreground'),
    divider: slot('border'),
  };
};
const palette = { light: paletteFor(lightMap), dark: paletteFor(darkMap) };

fs.writeFileSync(
  path.join(THEME_DIR, 'hds-palette.generated.ts'),
  '/* GENERATED by scripts/build-hds-tokens.mjs — HDS palette (light + dark) resolved to hex,\n' +
    '   jade brand applied. Source of truth: hirobius.tokens.json. Do not edit by hand. */\n' +
    'export const hdsPalette = ' +
    JSON.stringify(palette, null, 2) +
    ' as const;\n',
);
console.log('✓ wrote src/tokens/hds-tokens.css and src/theme/hds-palette.generated.ts');
console.log(palette);
